-- Control-plane database migration 001.
-- Apply ONLY to a dedicated, empty control-plane database. Never apply to a store DB.
-- IDs are generated by the trusted application layer; no extension is required.

BEGIN;

CREATE TABLE IF NOT EXISTS cp_accounts (
  id UUID PRIMARY KEY,
  primary_email TEXT NOT NULL,
  display_name TEXT,
  status TEXT NOT NULL DEFAULT 'ACTIVE'
    CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS cp_accounts_email_normalized_uq
  ON cp_accounts (lower(btrim(primary_email)));

CREATE TABLE IF NOT EXISTS cp_account_identities (
  id UUID PRIMARY KEY,
  account_id UUID NOT NULL REFERENCES cp_accounts(id) ON DELETE RESTRICT,
  provider TEXT NOT NULL CHECK (provider IN ('oidc', 'google', 'apple', 'email')),
  provider_subject TEXT NOT NULL,
  email TEXT,
  email_verified BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (provider, provider_subject)
);
CREATE INDEX IF NOT EXISTS cp_account_identities_account_idx
  ON cp_account_identities(account_id);

CREATE TABLE IF NOT EXISTS cp_stores (
  id UUID PRIMARY KEY,
  display_name TEXT NOT NULL CHECK (length(btrim(display_name)) BETWEEN 1 AND 160),
  status TEXT NOT NULL DEFAULT 'PROVISIONING'
    CHECK (status IN ('PROVISIONING', 'ACTIVE', 'SUSPENDED', 'FAILED', 'CLOSED')),
  created_by_account_id UUID NOT NULL REFERENCES cp_accounts(id) ON DELETE RESTRICT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS cp_store_memberships (
  id UUID PRIMARY KEY,
  account_id UUID NOT NULL REFERENCES cp_accounts(id) ON DELETE RESTRICT,
  store_id UUID NOT NULL REFERENCES cp_stores(id) ON DELETE RESTRICT,
  role TEXT NOT NULL CHECK (role IN ('OWNER', 'ADMIN', 'MANAGER', 'STAFF', 'READ_ONLY')),
  status TEXT NOT NULL DEFAULT 'ACTIVE'
    CHECK (status IN ('INVITED', 'ACTIVE', 'SUSPENDED', 'REVOKED')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (account_id, store_id),
  UNIQUE (account_id, store_id, id)
);
CREATE INDEX IF NOT EXISTS cp_memberships_account_status_idx
  ON cp_store_memberships(account_id, status, store_id);
CREATE INDEX IF NOT EXISTS cp_memberships_store_status_idx
  ON cp_store_memberships(store_id, status);

-- The value is an opaque secret-manager key/reference, never a password or URL.
CREATE TABLE IF NOT EXISTS cp_store_database_bindings (
  store_id UUID PRIMARY KEY REFERENCES cp_stores(id) ON DELETE RESTRICT,
  database_key TEXT NOT NULL UNIQUE
    CHECK (length(btrim(database_key)) BETWEEN 1 AND 200),
  status TEXT NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING', 'READY', 'UNAVAILABLE', 'RETIRED')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Store-scoped sessions reference an active membership. Only a hash of the
-- opaque bearer token is persisted; raw access tokens are never stored.
CREATE TABLE IF NOT EXISTS cp_sessions (
  id UUID PRIMARY KEY,
  account_id UUID NOT NULL REFERENCES cp_accounts(id) ON DELETE RESTRICT,
  active_store_id UUID,
  active_membership_id UUID,
  access_token_hash CHAR(64) NOT NULL UNIQUE
    CHECK (access_token_hash ~ '^[0-9a-f]{64}$'),
  expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at TIMESTAMPTZ,
  CONSTRAINT cp_session_membership_fk
    FOREIGN KEY (account_id, active_store_id, active_membership_id)
    REFERENCES cp_store_memberships(account_id, store_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT cp_session_store_pair_ck CHECK (
    (active_store_id IS NULL AND active_membership_id IS NULL) OR
    (active_store_id IS NOT NULL AND active_membership_id IS NOT NULL)
  )
);
CREATE INDEX IF NOT EXISTS cp_sessions_account_expiry_idx
  ON cp_sessions(account_id, expires_at)
  WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS cp_sessions_store_idx
  ON cp_sessions(active_store_id)
  WHERE revoked_at IS NULL;

COMMIT;
